  detail=call(tc,'assignment-detail',{'assignmentId':late['id']})['assignment'];call(tc,'update-assignment',{'assignmentId':late['id'],'revision':detail['revision'],'mutationId':str(uuid.uuid4()),'dueLocal':day(7)+'T23:59','rules':{'minMinutes':30,'minCards':100}});r=call(tc,'assignment-report',{'assignmentId':late['id']});grade=next(x for x in r['students'] if x['email']=='alex@example.com')['progress'];check(grade['creditPercent']==50 and grade['ready'],'extending a deadline keeps the earlier half-credit grade and original completion requirements')
