  t.set_viewport_size({'width':320,'height':568});check(t.evaluate('document.documentElement.scrollWidth<=innerWidth+1'),'teacher editing form fits a narrow phone width');t.locator('#assignment-edit-form [type=submit]').scroll_into_view_if_needed();check(t.locator('#assignment-edit-form [type=submit]').is_visible(),'all teacher settings remain reachable through normal dialog scrolling');t.screenshot(path=str(ROOT/'checks/assignment-edit-phone.png'));t.set_viewport_size({'width':1366,'height':900});t.screenshot(path=str(ROOT/'checks/assignment-edit-desktop.png'));t.keyboard.press('Escape')
